import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageClasses() {
  const [classes, setClasses] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editId, setEditId] = useState(null);
  const [formData, setFormData] = useState({ day: 'Monday', grade: 'Grade 10', subject: 'Mathematics', time_slot: '', teacher: '' });
  
  // Search & Filter States
  const [searchQuery, setSearchQuery] = useState(''); 
  const [filterGrade, setFilterGrade] = useState('All'); 

  // 🟢 දත්ත ලබා ගැනීම (Read)
  const fetchClasses = () => {
    axios.get('http://localhost:8081/api/timetable')
      .then(res => setClasses(res.data))
      .catch(err => console.error("Error fetching data:", err));
  };

  useEffect(() => { fetchClasses(); }, []);

  // 🟢 අලුත් පන්තියක් ඇතුළත් කිරීම හෝ Update කිරීම (Create & Update)
  const handleSubmit = (e) => {
    e.preventDefault();
    
    if (isEditing) {
      // Update කිරීම (මෙතනදී Backend එකේ PUT Route එකක් තියෙන්න ඕනේ)
      axios.put(`http://localhost:8081/api/timetable/${editId}`, formData)
        .then(res => {
          fetchClasses();
          resetForm();
          alert("✅ Class Schedule Updated Successfully!");
        })
        .catch(err => {
          console.error(err);
          alert("Error updating. Ensure backend PUT route exists.");
        });
    } else {
      // අලුතින් ඇතුළත් කිරීම (Save)
      axios.post('http://localhost:8081/api/timetable', formData)
        .then(res => {
          if(res.data.status === "Success") {
            fetchClasses();
            resetForm();
            alert("✅ Class Schedule Added Successfully!");
          }
        })
        .catch(err => console.error("Error saving data:", err));
    }
  };

  // 🟢 Delete කිරීම
  const handleDelete = (id) => {
    if(window.confirm("Are you sure you want to delete this class schedule?")) {
      axios.delete(`http://localhost:8081/api/timetable/${id}`)
        .then(res => {
          fetchClasses();
          alert("🗑️ Class Schedule Deleted!");
        })
        .catch(err => {
            console.error(err);
            alert("Error deleting. Ensure backend DELETE route exists.");
            // UI එකෙන් විතරක් අයින් කරලා පෙන්වන්න නම්:
            setClasses(classes.filter(c => c.id !== id)); 
        });
    }
  };

  // 🟢 Edit Button එක Click කළාම දත්ත Form එකට දැමීම
  const handleEdit = (cls) => {
    setIsEditing(true);
    setEditId(cls.id); // database ID එක
    setFormData({
      day: cls.day,
      grade: cls.grade,
      subject: cls.subject,
      time_slot: cls.time_slot,
      teacher: cls.teacher
    });
    setShowForm(true);
  };

  // 🟢 Form එක හිස් කිරීම
  const resetForm = () => {
    setShowForm(false);
    setIsEditing(false);
    setEditId(null);
    setFormData({ day: 'Monday', grade: 'Grade 10', subject: 'Mathematics', time_slot: '', teacher: '' });
  };

  // 🟢 Search සහ Filter කිරීම
  const filteredClasses = [...classes]
    .reverse()
    .filter(c => filterGrade === 'All' ? true : c.grade === filterGrade) // Grade Filter
    .filter(c => 
      c.subject.toLowerCase().includes(searchQuery.toLowerCase()) || 
      c.teacher.toLowerCase().includes(searchQuery.toLowerCase())
    ); // Search Box

  return (
    <div style={{ padding: '10px', fontFamily: 'sans-serif', animation: 'fadeIn 0.5s' }}>
      
      {/* 🟢 Header, Search, Filter & Add Button */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '25px', backgroundColor: '#fff', padding: '15px 20px', borderRadius: '12px', boxShadow: '0 2px 8px rgba(0,0,0,0.02)', flexWrap: 'wrap', gap: '15px' }}>
        <h2 style={{ margin: 0, color: '#1e293b', fontSize: '22px' }}>📅 Manage Class Timetable</h2>
        
        <div style={{ display: 'flex', gap: '15px', alignItems: 'center', flexWrap: 'wrap' }}>
          
          {/* 🔍 Search Bar */}
          <input 
            type="text" 
            placeholder="Search Subject or Teacher..." 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            style={{ padding: '8px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', width: '220px', fontSize: '13px' }}
          />

          {/* 🟢 Grade Filter Dropdown (ඔයා ඉල්ලපු දේ) */}
          <select 
            value={filterGrade} 
            onChange={(e) => setFilterGrade(e.target.value)} 
            style={{ padding: '8px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '13px', backgroundColor: '#f8fafc', color: '#475569', fontWeight: 'bold' }}>
            <option value="All">All Grades</option>
            {['Grade 06', 'Grade 07', 'Grade 08', 'Grade 09', 'Grade 10', 'Grade 11', 'A/L 2026', 'A/L 2027'].map(g => <option key={g} value={g}>{g}</option>)}
          </select>
          
          <button 
            onClick={() => { resetForm(); setShowForm(true); }} 
            style={{ padding: '8px 15px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', boxShadow: '0 4px 10px rgba(21,128,61,0.2)' }}>
            + Add New Class
          </button>
        </div>
      </div>

      {/* 🟢 Classes Table */}
      <div style={{ backgroundColor: '#fff', borderRadius: '12px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
              <th style={thStyle}>No.</th>
              <th style={thStyle}>Day & Time</th>
              <th style={thStyle}>Grade</th>
              <th style={thStyle}>Subject</th>
              <th style={thStyle}>Teacher</th>
              <th style={{...thStyle, textAlign: 'center'}}>Actions</th>
            </tr>
          </thead>
          <tbody>
            {filteredClasses.length > 0 ? filteredClasses.map((c, index) => (
              <tr key={c.id} style={{ borderBottom: '1px solid #f1f5f9', transition: '0.2s' }}>
                <td style={{...tdStyle, fontWeight: 'bold', color: '#1e293b'}}>{index + 1}</td>
                <td style={tdStyle}>
                  <div style={{ fontWeight: 'bold', color: '#15803d' }}>{c.day}</div>
                  <div style={{ fontSize: '12px', color: '#64748b' }}>{c.time_slot}</div>
                </td>
                <td style={tdStyle}>
                  <span style={{ backgroundColor: '#f1f5f9', padding: '4px 8px', borderRadius: '4px', fontSize: '12px', fontWeight: 'bold', color: '#475569' }}>{c.grade}</span>
                </td>
                <td style={{...tdStyle, fontWeight: 'bold', color: '#1e293b'}}>{c.subject}</td>
                <td style={{...tdStyle, color: '#64748b'}}>{c.teacher}</td>
                <td style={{...tdStyle, textAlign: 'center'}}>
                  <button onClick={() => handleEdit(c)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px', marginRight: '10px' }}>✏️</button>
                  <button onClick={() => handleDelete(c.id)} style={{ border: 'none', background: 'none', cursor: 'pointer', fontSize: '16px' }}>🗑️</button>
                </td>
              </tr>
            )) : (
              <tr>
                <td colSpan="6" style={{ padding: '30px', textAlign: 'center', color: '#94a3b8' }}>
                  No classes found for this criteria.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {/* 🟢 Add/Edit Class Modal Form */}
      {showForm && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.4)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 }}>
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', width: '450px', boxShadow: '0 10px 25px rgba(0,0,0,0.1)' }}>
            
            <h3 style={{ margin: '0 0 20px 0', color: '#1e293b', fontSize: '20px', borderBottom: '1px solid #f1f5f9', paddingBottom: '10px' }}>
              {isEditing ? '✏️ Edit Class Schedule' : '➕ Add Class Schedule'}
            </h3>
            
            <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              
              <select value={formData.day} onChange={(e) => setFormData({...formData, day: e.target.value})} style={inputStyle}>
                {['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'].map(d => <option key={d} value={d}>{d}</option>)}
              </select>
              
              <select value={formData.grade} onChange={(e) => setFormData({...formData, grade: e.target.value})} style={inputStyle}>
                {['Grade 06', 'Grade 07', 'Grade 08', 'Grade 09', 'Grade 10', 'Grade 11', 'A/L 2026', 'A/L 2027'].map(g => <option key={g} value={g}>{g}</option>)}
              </select>
              
              <select value={formData.subject} onChange={(e) => setFormData({...formData, subject: e.target.value})} style={inputStyle}>
                {['Mathematics', 'Science', 'English', 'Sinhala', 'ICT', 'Accounting', 'Business Studies', 'Economics', 'Physics', 'Dancing', 'History'].map(s => <option key={s} value={s}>{s}</option>)}
              </select>
              
              <input type="text" placeholder="Time Slot (e.g. 3.00 PM - 6.00 PM)" value={formData.time_slot} onChange={(e) => setFormData({...formData, time_slot: e.target.value})} required style={inputStyle} />
              
              <input type="text" placeholder="Teacher Name" value={formData.teacher} onChange={(e) => setFormData({...formData, teacher: e.target.value})} required style={inputStyle} />
              
              {/* Buttons */}
              <div style={{ display: 'flex', justifyContent: 'flex-end', gap: '12px', marginTop: '10px' }}>
                <button type="button" onClick={resetForm} style={{ padding: '10px 20px', backgroundColor: '#f1f5f9', color: '#475569', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }}>Cancel</button>
                <button type="submit" style={{ padding: '10px 25px', backgroundColor: isEditing ? '#3b82f6' : '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', boxShadow: isEditing ? '0 4px 10px rgba(59,130,246,0.2)' : '0 4px 10px rgba(21,128,61,0.2)' }}>
                  {isEditing ? 'Update Class' : 'Save Class'}
                </button>
              </div>
            </form>

          </div>
        </div>
      )}
    </div>
  );
}

// Styles
const inputStyle = { padding: '10px 15px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '14px', outline: 'none', width: '100%', boxSizing: 'border-box' };
const thStyle = { padding: '15px', color: '#475569', fontSize: '14px', textAlign: 'left' };
const tdStyle = { padding: '15px', fontSize: '14px' };
